import { create } from 'zustand';
import type { FeatureCollection } from 'geojson';
import { feature } from 'topojson-client';
import type { Topology, GeometryCollection } from 'topojson-specification';
import type { ProjectionVariant } from '../utils/projectionVariants';
import { variantDef, defaultVariant } from '../utils/projectionVariants';

export type ProjectionFamily = 'cylindrical' | 'conic' | 'azimuthalPerspective';
export type DistortionModel = 'conformal' | 'equalArea' | 'equidistant';

// Light-source modes for the azimuthal family. The projection is generated by a
// point light whose position defines it: `center` → gnomonic, `antipode` →
// stereographic, `infinity` → orthographic (parallel beams).
export type AzimuthalLight = 'center' | 'antipode' | 'infinity';

// The visualization method shown in the 3D scene (section 13 of the plan).
export type VizMethod =
  | 'none'
  | 'normals'
  | 'particles'
  | 'magnetic'
  | 'peel'
  | 'wave'
  | 'laser'
  | 'construction'
  | 'shadow';

// Distortion heatmap colouring mode.
export type HeatmapType = 'area' | 'angle' | 'scale';

// Test-figure overlay type on the 2D map.
export type TestFigureType = 'circles' | 'squares' | 'faces';

// Graticule step in degrees.
export type GraticuleStep = 1 | 5 | 10 | 15 | 30;

// Cone hemisphere selector (north / south).
export type ConeHemisphere = 'north' | 'south';

// Default distortion per family: cylindrical → conformal, conic → equidistant,
// azimuthal perspective → conformal.
export const DEFAULT_DISTORTION: Record<ProjectionFamily, DistortionModel> = {
  cylindrical: 'conformal',
  conic: 'equidistant',
  azimuthalPerspective: 'conformal',
};

export interface ProjectionParams {
  variant: ProjectionVariant;
  family: ProjectionFamily;
  distortion: DistortionModel;
  lambda0: number; // -180...180  (central meridian)
  phiOrigin: number; // -90...90   (central latitude)
  scaleFactor: number; // aux-figure immersion; slider 0.9...1.1 (conic/azimuthal) or 0.5...1.0 for cylindrical (1.0 = Earth-diameter cylinder, 0.5 = half)
  falseEasting: number; // -1000...1000
  falseNorthing: number; // -1000...1000
  gamma: number; // -180...180  (tilt / third rotation → oblique & transverse aspects)
  stdParallel2: number | null; // φ2; null = tangent surface (single standard parallel)
  azLight: AzimuthalLight; // light-source mode for the azimuthal family

  // Ruler (distance measurement) state.
  rulerMode: 'off' | 'first' | 'second' | 'done';
  rulerPoint1: [number, number] | null;
  rulerPoint2: [number, number] | null;

  // Cone hemisphere (north / south).
  coneHemisphere: ConeHemisphere;
}

export function defaultParamsForFamily(family: ProjectionFamily): ProjectionParams {
  const v = defaultVariant(family);
  const def = variantDef(v);
  return {
    variant: v,
    family: def.family,
    distortion: def.distortion,
    lambda0: 0,
    phiOrigin: 0,
    scaleFactor: def.lockedScaleFactor ?? 1,
    falseEasting: 0,
    falseNorthing: 0,
    gamma: def.lockedGamma ?? 0,
    stdParallel2: def.lockedStdParallel2 ?? null,
    azLight: def.azLight,
    rulerMode: 'off',
    rulerPoint1: null,
    rulerPoint2: null,
    coneHemisphere: 'north',
  };
}

interface AppState extends ProjectionParams {
  // Monotonic token for loadGeoData: a newer fetch supersedes an older one.
  _geoToken: number;
  showTissot: boolean;
  showBorders: boolean;
  // White lines marking where the auxiliary (developable) surface intersects
  // the globe, drawn on the 2D map (the 3D scene always draws them).
  showIntersection: boolean;
  // 3D globe keeps the lightweight 110m land; 2D map uses the detailed 50m datasets.
  geoJsonData: FeatureCollection | null;
  land50GeoJson: FeatureCollection | null;
  countriesGeoJson: FeatureCollection | null;
  // True while the bundled geodata is being fetched (used to show a loading hint
  // and to ignore a late response after unmount / re-fetch).
  geoLoading: boolean;
  // 110m country borders, used by the lightweight (non-detailed) 2D map.
  countries110GeoJson: FeatureCollection | null;
  // Friendly Russian error message set when BOTH the 110m and 50m land fetches
  // fail (so the 2D map has nothing to render). null otherwise — a partial
  // failure (one of four files) is silent because the surviving layers still
  // produce a usable map. `Map2D` shows this in its empty-map overlay so the
  // user knows to reload the page instead of seeing a bare «Нет геоданных».
  geoDataError: string | null;
  // When true the 2D map uses the detailed 50m land + country borders; otherwise the
  // lightweight 110m land (shared with the 3D globe) is drawn without borders.
  detailedMap: boolean;

  // The point currently hovered in either the 2D map or the 3D globe, shared so
  // the other view can mirror the highlight (see AGENTS.md for the cross-linking model).
  // `hoverSource` records which view set it, so the projection ray is drawn only
  // when the 2D map is hovered (the 3D globe mirrors the marker, not the ray).
  hoverLonLat: [number, number] | null;
  hoverSource: 'globe' | 'map' | null;
  setHoverLonLat: (v: [number, number] | null, source?: 'globe' | 'map') => void;
  // Toggle the cursor-driven projection ray (drawn in the 3D scene only while the
  // 2D map is hovered). Independent of the always-on central-meridian ray fan.
  showHoverRay: boolean;
  setShowHoverRay: (value: boolean) => void;

  // --- Non-parametric visualization / interaction state ---
  vizMethod: VizMethod;
  showHeatmap: boolean;
  heatmapType: HeatmapType;
  graticuleStep: GraticuleStep;
  showGraticule: boolean;
  testFigureType: TestFigureType | null;
  showRays: boolean;
  rulerActive: boolean;
  unfoldTrigger: boolean;

  setParam: <K extends keyof ProjectionParams>(key: K, value: ProjectionParams[K]) => void;
  setVariant: (v: ProjectionVariant) => void;
  setShowTissot: (value: boolean) => void;
  setShowBorders: (value: boolean) => void;
  setShowIntersection: (value: boolean) => void;
  setDetailedMap: (value: boolean) => void;
  setFamily: (family: ProjectionFamily) => void;
  resetParams: () => void;
  loadGeoData: () => Promise<void>;
  applyPreset: (preset: Partial<ProjectionParams & { vizMethod?: VizMethod }>) => void;

  setVizMethod: (v: VizMethod) => void;
  setShowHeatmap: (value: boolean) => void;
  setHeatmapType: (value: HeatmapType) => void;
  setGraticuleStep: (value: GraticuleStep) => void;
  setShowGraticule: (value: boolean) => void;
  setTestFigureType: (value: TestFigureType | null) => void;
  setShowRays: (value: boolean) => void;
  setRulerActive: (value: boolean) => void;
  setRulerMode: (value: 'off' | 'first' | 'second' | 'done') => void;
  setRulerPoint1: (value: [number, number] | null) => void;
  setRulerPoint2: (value: [number, number] | null) => void;
  setConeHemisphere: (value: ConeHemisphere) => void;
  startUnfold: () => void;
  finishUnfold: () => void;
}

// The full set of new (variant-defaultable) fields reset by setVariant /
// resetParams / applyPreset. Keeping them in one record guarantees the variant
// switch never leaves stale state behind.
const NEW_DEFAULTS = {
  rulerMode: 'off' as const,
  rulerPoint1: null,
  rulerPoint2: null,
  coneHemisphere: 'north' as ConeHemisphere,
};

export const useAppStore = create<AppState>((set) => ({
  ...defaultParamsForFamily('cylindrical'),
  _geoToken: 0,
  showTissot: false,
  showBorders: false,
  showIntersection: false,
  geoJsonData: null,
  land50GeoJson: null,
  countriesGeoJson: null,
  countries110GeoJson: null,
  geoLoading: false,
  geoDataError: null,
  detailedMap: false,
  hoverLonLat: null,
  hoverSource: null,
  showHoverRay: false,
  vizMethod: 'none',
  showHeatmap: false,
  heatmapType: 'area',
  graticuleStep: 15,
  showGraticule: true,
  testFigureType: null,
  showRays: true,
  rulerActive: false,
  unfoldTrigger: false,
  setHoverLonLat: (v, source) => set({ hoverLonLat: v, hoverSource: source ?? null }),
  setShowHoverRay: (value) => set({ showHoverRay: value }),

  setParam: (key, value) => {
    // Guard: the azimuthal-perspective family has no equal-area projection
    // (area is routed by azLight, not by distortion). Reject an equalArea
    // distortion there so the store can never hold a broken combination.
    if (key === 'distortion' && value === 'equalArea') {
      const family = useAppStore.getState().family;
      if (family === 'azimuthalPerspective') return;
    }
    set({ [key]: value } as Pick<AppState, typeof key>);
  },
  setVariant: (v) => {
    const def = variantDef(v);
    set({
      variant: v,
      family: def.family,
      distortion: def.distortion,
      azLight: def.azLight,
      vizMethod: def.recommendedVizMethod,
      gamma: def.lockedGamma ?? 0,
      scaleFactor: def.lockedScaleFactor ?? 1,
      phiOrigin: 0,
      lambda0: 0,
      stdParallel2: def.lockedStdParallel2 ?? null,
      ...NEW_DEFAULTS,
    });
  },
  setShowTissot: (value) => set({ showTissot: value }),
  setShowBorders: (value) => set({ showBorders: value }),
  setShowIntersection: (value) => set({ showIntersection: value }),
  setDetailedMap: (value) => set({ detailedMap: value }),
  setFamily: (family) =>
    set((s) => ({
      // Keep the user's generic placement params (central meridian, central
      // latitude, tilt) and only reset the family-specific defaults so a family
      // switch doesn't wipe the whole configuration.
      ...defaultParamsForFamily(family),
      lambda0: s.lambda0,
      phiOrigin: 0,
      gamma: 0,
      falseEasting: s.falseEasting,
      falseNorthing: s.falseNorthing,
    })),
  resetParams: () => set((s) => {
    // Reset the params of the CURRENTLY selected projection: keep the variant
    // (the projection itself) and only restore its default parameter values.
    const v = s.variant ?? defaultVariant(s.family);
    const def = variantDef(v);
    return {
      variant: v,
      family: def.family,
      distortion: def.distortion,
      azLight: def.azLight,
      lambda0: 0,
      phiOrigin: 0,
      scaleFactor: def.lockedScaleFactor ?? 1,
      falseEasting: 0,
      falseNorthing: 0,
      gamma: def.lockedGamma ?? 0,
      stdParallel2: def.lockedStdParallel2 ?? null,
      ...NEW_DEFAULTS,
    };
  }),
  applyPreset: (preset) =>
    set((s) => {
      const merged = { ...s, ...preset } as Partial<ProjectionParams> & {
        variant?: ProjectionVariant;
        family?: ProjectionFamily;
        distortion?: DistortionModel;
      };
      // Guard against an inconsistent variant/family/distortion combination that
      // would produce a broken projection. If the merged variant belongs to a
      // different family than the merged family, reset the variant to the
      // family's default.
      const def = merged.variant ? variantDef(merged.variant) : null;
      const nextFamily = merged.family ?? s.family;
      if (def && def.family !== nextFamily) {
        const v = defaultVariant(nextFamily);
        const vDef = variantDef(v);
        return {
          ...preset,
          variant: v,
          family: vDef.family,
          distortion: vDef.distortion,
          azLight: vDef.azLight,
        };
      }
      return { ...preset };
    }),
  loadGeoData: async () => {
    // A monotonically increasing token lets a later call supersede an earlier one
    // (e.g. on a fast remount): only the most recent fetch may commit its result.
    const token = useAppStore.getState()._geoToken ?? 0;
    const next = token + 1;
    useAppStore.setState({ _geoToken: next });
    set({ geoLoading: true, geoDataError: null });

    const load = async (url: string, object: string): Promise<FeatureCollection | null> => {
      try {
        const response = await fetch(url);
        if (!response.ok) throw new Error(`Failed to load ${url}: ${response.status}`);
        const topology = (await response.json()) as Topology;
        const geometry = topology.objects[object] as GeometryCollection;
        return feature(topology, geometry) as FeatureCollection;
      } catch (err) {
        console.error('loadGeoData failed:', url, err);
        return null;
      }
    };
    const [land110, land50, countries, countries110] = await Promise.all([
      load('/world-110m.topojson', 'land'),
      load('/land-50m.json', 'land'),
      load('/countries-50m.json', 'countries'),
      load('/countries-110m.json', 'countries'),
    ]);
    // Ignore stale results: if a newer load started while we were fetching, the
    // newer call owns the committed state and this one must not overwrite it.
    if (useAppStore.getState()._geoToken !== next) return;
    // If BOTH base land layers failed the 2D map has nothing to render — surface
    // a friendly message so the user knows to reload instead of staring at an
    // unexplained empty panel. A partial failure (any one of the four files)
    // leaves enough data for a usable map and stays silent.
    const totalLandFailure = !land110 && !land50;
    set({
      geoJsonData: land110,
      land50GeoJson: land50,
      countriesGeoJson: countries,
      countries110GeoJson: countries110,
      geoLoading: false,
      geoDataError: totalLandFailure
        ? 'Не удалось загрузить карту. Проверьте подключение к интернету и перезагрузите страницу.'
        : null,
    });
  },

  setVizMethod: (v) => set({ vizMethod: v }),
  setShowHeatmap: (value) => set({ showHeatmap: value }),
  setHeatmapType: (value) => set({ heatmapType: value }),
  setGraticuleStep: (value) => set({ graticuleStep: value }),
  setShowGraticule: (value) => set({ showGraticule: value }),
  setTestFigureType: (value) => set({ testFigureType: value }),
  setShowRays: (value) => set({ showRays: value }),
  setRulerActive: (value) => set({ rulerActive: value, rulerMode: value ? 'first' : 'off' }),
  setRulerMode: (value) => set({ rulerMode: value }),
  setRulerPoint1: (value) => set({ rulerPoint1: value }),
  setRulerPoint2: (value) => set({ rulerPoint2: value }),
  setConeHemisphere: (value) => set({ coneHemisphere: value }),
  startUnfold: () => set({ unfoldTrigger: true }),
  finishUnfold: () => set({ unfoldTrigger: false }),
}));
